B='W11-L53';WHO='build_offline_study_interface:L53-v2-repair';old=json.loads((R/f'data/history/{B}/{B}-v1.json').read_text());d=copy.deepcopy(old);qs={q['id']:q for q in d['questions']};summary=json.loads((R/f'audits/{B}-contracts-review-summary.json').read_text());flags=summary['flaggedFindings'];changed=set()
