def q(n):return qs[f'{B}-Q{n:03d}']
def edit(n,opts=None,stem=None,why=None,typ=None,difficulty=None,steps=None,forms=None,assumptions=None):
 x=q(n);assert x['id'] in flags
 if x['id'] not in changed:x.update(version=x['version']+1,status='draft',reviewIds=[],revisionAuthors=list(dict.fromkeys(x.get('revisionAuthors',[])+[WHO])));changed.add(x['id'])
 if stem:x['stem']=stem
 if why:x['solution']['justification']=why;x['solution']['simpleExplanation']=why
 if typ:x['type']=typ;x['cognitiveSkill']='numerical' if typ=='numerical' else 'application' if typ in ['scenario','diagram'] else 'conceptual'
 if difficulty:x['difficulty']=difficulty
 if steps is not None:x['solution']['steps']=steps
 if forms is not None:x['solution']['formulas']=forms
 if assumptions is not None:x['assumptions']=assumptions
 if opts:
  key=x['correctOptionIds'][0];ids=[key]+[o['id'] for o in x['options'] if o['id']!=key];mp=dict(zip(ids,opts));assert len(mp)==4
  for o in x['options']:o['text']=mp[o['id']][0]
  x['solution']['optionExplanations']={i:z[1] for i,z in mp.items()};x['solution']['misconceptions']=[z[1] for i,z in mp.items() if i!=key]
 return x
def cite(x,p,kind,locator,role='premise'):
 c=dict(slideId=f'lectures-p{p:04d}',sourceId='lectures',sourceSha256=SHA,physicalPage=p,kind=kind,locator=f'Lecture L53, physical PDF page {p}, printed footer {p-1684}: {locator}',evidenceText=(R/f'sources/text/lectures/page-{p:04d}.txt').read_text().strip(),role=role,region=None)
 x['citations'].append(c)
 for cpt in d['concepts']:
  if cpt['id'] in x['conceptIds'] and c['slideId'] not in cpt['slideIds']:cpt['slideIds'].append(c['slideId'])
 return c
