edit(22,[('A real freely running shaft can still need electromagnetic torque and current to overcome internal losses.','Zero external load does not eliminate friction or iron losses.'),('Zero external load makes electromagnetic torque exactly zero even when internal friction is nonzero.','At steady speed the motor must balance internal resisting torque as well as external load.'),('Internal friction can be supplied by back EMF alone without electromagnetic torque.','Back EMF is an electrical effect, not an independent mechanical driving torque.'),('All no-load input power becomes useful external shaft power because the shaft is rotating.','At zero external load, useful external torque power is zero while losses may consume input power.')])
edit(30,[('A series drive needs appropriate loading and speed protection rather than assuming unloaded operation is harmless.','Small load current weakens the field, so high speed may be needed to develop back EMF.'),('A current limiter alone fixes the no-load speed at a safe rated value, independent of field weakening.','Limiting current does not by itself impose the needed mechanical speed limit.'),('A weaker no-load field necessarily lowers speed because magnetic torque is weaker.','This ignores the back-EMF requirement as flux falls.'),('The high starting-torque rating establishes the continuous safe speed limit without a separate speed rating.','Starting torque and overspeed constraints are different ratings.')])
edit(32,forms=[formula('I_a=(V−V_b)/R_a; I_f=V/R_f; I_line=I_a+I_f',{'I_a':'armature current','I_f':'shunt-field current','I_line':'supply current','V':'common supply voltage across the correctly connected branches','V_b':'armature back EMF','R_a':'armature resistance','R_f':'field resistance'},{'I_a,I_f,I_line':'A','V,V_b':'V','R_a,R_f':'Ω'},['Declared correct shunt connection; steady electrical conditions; no transient inductive voltage.'])]);cite(q(32),1694,'equation','Armature current I=(V−V_b)/R after inductance is neglected.')
edit(33,[('Speed changes relatively little with load, but armature resistive drop can still reduce it.','Good regulation is approximate, not exact load independence.'),('Increasing armature current raises back EMF because RI is added to the fixed supply voltage.','The steady relation is V_b=V−RI, not V+RI.'),('Armature current stays fixed when torque changes because the shunt field current is nearly fixed.','This confuses separate field current with load-dependent armature current.'),('The armature resistive drop changes only current and cannot affect speed at fixed field.','At fixed supply and field, a changed RI drop changes back EMF and therefore speed.')])
